dashboard.definition:
{
	"title": "Zero Trust Access",
	"description": "Secure Networking drill-down dashboard for Zero Trust Access.",
	"inputs": {
		"input_time_range": {
			"options": {
				"defaultValue": "-24h@h,now",
				"token": "time_tok"
			},
			"title": "Time Range",
			"type": "input.timerange"
		}
	},
	"defaults": {
		"visualizations": {
			"global": {
				"showLastUpdated": true,
				"showProgressBar": true
			}
		}
	},
	"visualizations": {
		"viz_header_bg": {
			"type": "splunk.rectangle",
			"options": {
				"fillColor": "#0f172a",
				"strokeColor": "rgba(148,163,184,0.22)"
			}
		},
		"viz_header_icon": {
			"type": "splunk.image",
			"title": "Zero Trust Access",
			"options": {
				"preserveAspectRatio": true,
				"src": "/static/app/splunk-cisco-dashboards/images/overview/secure-networking/zero-trust-access.svg"
			}
		},
		"viz_header": {
			"type": "splunk.markdown",
			"title": "",
			"showLastUpdated": false,
			"showProgressBar": false,
			"options": {
				"backgroundColor": "transparent",
				"fontColor": "#e2e8f0",
				"markdown": "# Zero Trust Access\nIdentity enforcement, policy outcomes, ZTNA sessions, and authentication friction."
			}
		},
		"viz_zta_auth_events": {
			"type": "splunk.singlevalue",
			"title": "ISE Auth Events",
			"dataSources": {
				"primary": "ds_zta_auth_events"
			},
			"options": {
				"backgroundColor": "#0f172a",
				"majorFontSize": 36,
				"majorValue": "> primary | seriesByName('auth_events') | lastPoint()",
				"shouldAbbreviateMajorValue": true,
				"sparklineDisplay": "off",
				"trendDisplay": "off",
				"majorColor": "#0ea5e9"
			}
		},
		"viz_zta_failed_auth": {
			"type": "splunk.singlevalue",
			"title": "Failed Auth",
			"dataSources": {
				"primary": "ds_zta_failed_auth"
			},
			"options": {
				"backgroundColor": "#0f172a",
				"majorFontSize": 36,
				"majorValue": "> primary | seriesByName('failed_auth') | lastPoint()",
				"shouldAbbreviateMajorValue": true,
				"sparklineDisplay": "off",
				"trendDisplay": "off",
				"majorColor": "#dc2626"
			}
		},
		"viz_zta_failed_pct": {
			"type": "splunk.singlevalueradial",
			"title": "Auth Failure Rate",
			"dataSources": {
				"primary": "ds_zta_failed_pct"
			},
			"options": {
				"backgroundColor": "#0f172a",
				"majorFontSize": 36,
				"majorValue": "> primary | seriesByName('failed_pct') | lastPoint()",
				"shouldAbbreviateMajorValue": true,
				"sparklineDisplay": "off",
				"trendDisplay": "off",
				"majorColor": "> primary | seriesByName('failed_pct') | lastPoint() | rangeValue(lowerBetter)",
				"unit": "%"
			},
			"context": {
				"lowerBetter": [
					{
						"to": 1,
						"value": "#16a34a"
					},
					{
						"from": 1,
						"to": 5,
						"value": "#eab308"
					},
					{
						"from": 5,
						"value": "#dc2626"
					}
				]
			}
		},
		"viz_zta_feed_health": {
			"type": "splunk.singlevalueradial",
			"title": "ISE Feed Age",
			"dataSources": {
				"primary": "ds_zta_feed_health"
			},
			"options": {
				"backgroundColor": "#0f172a",
				"majorFontSize": 36,
				"majorValue": "> primary | seriesByName('age_minutes') | lastPoint()",
				"shouldAbbreviateMajorValue": true,
				"sparklineDisplay": "off",
				"trendDisplay": "off",
				"majorColor": "> primary | seriesByName('age_minutes') | lastPoint() | rangeValue(staleness)",
				"unit": "min"
			},
			"context": {
				"staleness": [
					{
						"to": 30,
						"value": "#16a34a"
					},
					{
						"from": 30,
						"to": 90,
						"value": "#eab308"
					},
					{
						"from": 90,
						"value": "#dc2626"
					}
				]
			}
		},
		"viz_zta_auth_outcome": {
			"type": "splunk.area",
			"title": "Authentication Outcome Trend",
			"dataSources": {
				"primary": "ds_zta_auth_outcome_trend"
			},
			"options": {
				"backgroundColor": "#0f172a",
				"legendDisplay": "right",
				"showYMajorGridLines": true,
				"xAxisTitleVisibility": "hide",
				"yAxisTitleVisibility": "hide",
				"seriesColors": [
					"#16a34a",
					"#dc2626",
					"#64748b"
				],
				"stackMode": "stacked",
				"lineWidth": 2,
				"nullValueDisplay": "gaps"
			}
		},
		"viz_zta_radius_latency": {
			"type": "splunk.line",
			"title": "RADIUS Latency by ISE Node",
			"dataSources": {
				"primary": "ds_zta_radius_latency"
			},
			"options": {
				"backgroundColor": "#0f172a",
				"legendDisplay": "right",
				"showYMajorGridLines": true,
				"xAxisTitleVisibility": "hide",
				"yAxisTitleVisibility": "hide",
				"seriesColors": [
					"#2563eb",
					"#16a34a",
					"#f59e0b",
					"#dc2626"
				],
				"lineWidth": 2,
				"nullValueDisplay": "gaps"
			}
		},
		"viz_zta_ztna_status": {
			"type": "splunk.area",
			"title": "ZTNA Connection Status",
			"dataSources": {
				"primary": "ds_zta_ztna_status"
			},
			"options": {
				"backgroundColor": "#0f172a",
				"legendDisplay": "right",
				"showYMajorGridLines": true,
				"xAxisTitleVisibility": "hide",
				"yAxisTitleVisibility": "hide",
				"seriesColors": [
					"#16a34a",
					"#f59e0b",
					"#dc2626",
					"#64748b"
				],
				"stackMode": "stacked",
				"lineWidth": 2,
				"nullValueDisplay": "gaps"
			}
		},
		"viz_zta_auth_by_device": {
			"type": "splunk.table",
			"title": "Auth Failure Rate by Network Device",
			"dataSources": {
				"primary": "ds_zta_auth_by_device"
			},
			"options": {
				"backgroundColor": "#0f172a",
				"count": 20,
				"fontSize": "small",
				"showInternalFields": false
			}
		},
		"viz_zta_failure_reasons": {
			"type": "splunk.bar",
			"title": "Top Authentication Failure Reasons",
			"dataSources": {
				"primary": "ds_zta_failure_reasons"
			},
			"options": {
				"backgroundColor": "#0f172a",
				"legendDisplay": "off",
				"showYMajorGridLines": true,
				"xAxisTitleVisibility": "hide",
				"yAxisTitleVisibility": "hide",
				"seriesColors": [
					"#dc2626"
				]
			}
		},
		"viz_zta_user_cross_source": {
			"type": "splunk.table",
			"title": "Cross-Source User Activity",
			"dataSources": {
				"primary": "ds_zta_user_cross_source"
			},
			"options": {
				"backgroundColor": "#0f172a",
				"count": 20,
				"fontSize": "small",
				"showInternalFields": false
			}
		},
		"viz_zta_ravpn_connection_rate": {
			"type": "splunk.line",
			"title": "Remote Access VPN Clients, Sessions, and Connect Rate",
			"dataSources": {
				"primary": "ds_zta_ravpn_connection_rate"
			},
			"options": {
				"backgroundColor": "#0f172a",
				"legendDisplay": "right",
				"showYMajorGridLines": true,
				"xAxisTitleVisibility": "hide",
				"yAxisTitleVisibility": "hide",
				"seriesColors": [
					"#2563eb",
					"#0ea5e9",
					"#16a34a",
					"#dc2626"
				],
				"lineWidth": 2,
				"nullValueDisplay": "gaps"
			}
		},
		"viz_zta_ravpn_posture_alerts": {
			"type": "splunk.table",
			"title": "Remote Access VPN Posture Alerts and Logs",
			"dataSources": {
				"primary": "ds_zta_ravpn_posture_alerts"
			},
			"options": {
				"backgroundColor": "#0f172a",
				"count": 20,
				"fontSize": "small",
				"showInternalFields": false
			}
		}
	},
	"dataSources": {
		"ds_zta_auth_events": {
			"name": "Secure Networking chain - ZTA auth event count",
			"options": {
				"ref": "secure_networking_zta_ise_auth_events_count",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.searchbase"
		},
		"ds_zta_failed_auth": {
			"name": "Secure Networking chain - ZTA failed auth count",
			"options": {
				"ref": "secure_networking_zta_ise_failed_auth_count",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.searchbase"
		},
		"ds_zta_failed_pct": {
			"name": "Secure Networking chain - ZTA failure rate",
			"options": {
				"ref": "secure_networking_zta_ise_failed_auth_pct",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.searchbase"
		},
		"ds_zta_feed_health": {
			"name": "Feed Monitor - ISE - RADIUS Syslog Staleness - Signal Rail KPI",
			"options": {
				"ref": "feed_monitor_ise_syslog_staleness",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.searchbase"
		},
		"ds_zta_auth_outcome_trend": {
			"name": "Secure Networking chain - ZTA auth outcome trend",
			"options": {
				"ref": "secure_networking_zta_auth_outcome_trend",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.searchbase"
		},
		"ds_zta_radius_latency": {
			"name": "Security Resilience - ISE RADIUS Request Latency",
			"options": {
				"ref": "security_resilience_ise_radius_latency",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.searchbase"
		},
		"ds_zta_ztna_status": {
			"name": "Secure Networking - ZTA ZTNA Connection Status Trend",
			"options": {
				"ref": "secure_networking_zta_ztna_connection_status_trend",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.searchbase"
		},
		"ds_zta_auth_by_device": {
			"name": "Secure Networking chain - ZTA auth failure by device",
			"options": {
				"ref": "secure_networking_zta_ise_auth_by_device_fail_rate",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.searchbase"
		},
		"ds_zta_failure_reasons": {
			"name": "Secure Networking chain - ZTA failure reasons by site",
			"options": {
				"ref": "secure_networking_zta_failure_reasons_by_site",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.searchbase"
		},
		"ds_zta_user_cross_source": {
			"name": "Secure Networking - ZTA User Activity Cross-Source Correlation",
			"options": {
				"ref": "secure_networking_zta_user_activity_cross_source",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.searchbase"
		},
		"ds_zta_ravpn_connection_rate": {
			"name": "Secure Networking - ZTA RaVPN Connection Rate and Clients",
			"options": {
				"ref": "secure_networking_zta_ravpn_connection_rate",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.searchbase"
		},
		"ds_zta_ravpn_posture_alerts": {
			"name": "Secure Networking - ZTA RaVPN Posture Alerts and Logs",
			"options": {
				"ref": "secure_networking_zta_ravpn_posture_alerts",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.searchbase"
		}
	},
	"layout": {
		"globalInputs": [
			"input_time_range"
		],
		"layoutDefinitions": {
			"layout_overview": {
				"options": {
					"backgroundColor": "#020617",
					"display": "auto-scale",
					"height": 1900,
					"width": 1440
				},
				"structure": [
					{
						"item": "viz_header_bg",
						"position": {
							"x": 20,
							"y": 0,
							"w": 1400,
							"h": 90
						},
						"type": "block"
					},
					{
						"item": "viz_header_icon",
						"position": {
							"x": 36,
							"y": 9,
							"w": 72,
							"h": 72
						},
						"type": "block"
					},
					{
						"item": "viz_header",
						"position": {
							"x": 120,
							"y": 0,
							"w": 1300,
							"h": 90
						},
						"type": "block"
					},
					{
						"item": "viz_zta_auth_events",
						"position": {
							"x": 20,
							"y": 110,
							"w": 335,
							"h": 180
						},
						"type": "block"
					},
					{
						"item": "viz_zta_failed_auth",
						"position": {
							"x": 375,
							"y": 110,
							"w": 335,
							"h": 180
						},
						"type": "block"
					},
					{
						"item": "viz_zta_failed_pct",
						"position": {
							"x": 730,
							"y": 110,
							"w": 335,
							"h": 180
						},
						"type": "block"
					},
					{
						"item": "viz_zta_feed_health",
						"position": {
							"x": 1085,
							"y": 110,
							"w": 335,
							"h": 180
						},
						"type": "block"
					},
					{
						"item": "viz_zta_auth_outcome",
						"position": {
							"x": 20,
							"y": 310,
							"w": 690,
							"h": 340
						},
						"type": "block"
					},
					{
						"item": "viz_zta_radius_latency",
						"position": {
							"x": 730,
							"y": 310,
							"w": 690,
							"h": 340
						},
						"type": "block"
					},
					{
						"item": "viz_zta_ztna_status",
						"position": {
							"x": 20,
							"y": 670,
							"w": 690,
							"h": 390
						},
						"type": "block"
					},
					{
						"item": "viz_zta_auth_by_device",
						"position": {
							"x": 730,
							"y": 670,
							"w": 690,
							"h": 390
						},
						"type": "block"
					},
					{
						"item": "viz_zta_failure_reasons",
						"position": {
							"x": 20,
							"y": 1080,
							"w": 690,
							"h": 390
						},
						"type": "block"
					},
					{
						"item": "viz_zta_user_cross_source",
						"position": {
							"x": 730,
							"y": 1080,
							"w": 690,
							"h": 390
						},
						"type": "block"
					},
					{
						"item": "viz_zta_ravpn_connection_rate",
						"position": {
							"x": 20,
							"y": 1490,
							"w": 690,
							"h": 390
						},
						"type": "block"
					},
					{
						"item": "viz_zta_ravpn_posture_alerts",
						"position": {
							"x": 730,
							"y": 1490,
							"w": 690,
							"h": 390
						},
						"type": "block"
					}
				],
				"type": "absolute"
			}
		},
		"options": {
			"showTitleAndDescription": false,
			"submitButton": false,
			"submitOnDashboardLoad": true
		},
		"tabs": {
			"items": [
				{
					"label": "overview",
					"layoutId": "layout_overview"
				}
			]
		}
	},
	"applicationProperties": {
		"collapseNavigation": false,
		"hideEdit": false,
		"hideExport": false
	}
}
